// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(uint8 len, uint256 seed) public {
        vm.assume(len >= 2);
        uint256 length = uint256(len);

        address from = address(this);
        address caddress = address(new CallCounter());

        address[] memory _tos = new address[](length);
        uint256[] memory v = new uint256[](length);
        for (uint256 i = 0; i < length; i++) {
            _tos[i] = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            v[i] = 1;
        }

        c.transfer(from, caddress, _tos, v);

        uint256 actualCalls = CallCounter(caddress).callCount();
        assertTrue(actualCalls == length);
    }
}

contract CallCounter {
    uint256 public callCount;

    function transferFrom(address, address, uint256) external {
        callCount++;
    }
}
